import React, { useState } from "react";
import { Form, FormGroup, Label, Input, Row, Col } from "reactstrap";
import "../Styles/CompanyRegister.css";

const StudentRegister = () => {
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [major, setMajor] = useState("IT");
  const [status, setStatus] = useState("Student"); // Student OR Graduate
  const [password, setPassword] = useState("");

  const MAJORS = [
    "Information Technology",
    "Business Administration",
    "Engineering",
    "Mass Communication",
  ];

  const handleSubmit = (e) => {
    e.preventDefault();
    const payload = { fullName, email, major, status, password };
    console.log("Student payload:", payload);
    alert("Student Registered ✅ (mock)");
  };

  return (
    <div className="reg-page">
      <h1 className="reg-title">
        Create your <span className="accent">account</span>
      </h1>
      <p className="reg-sub">Please fill in your details to continue:</p>

      <div className="reg-card">
        <Form onSubmit={handleSubmit}>
          {/* Full Name */}
          <FormGroup>
            <Label>Full Name</Label>
            <Input
              type="text"
              placeholder="Your name"
              value={fullName}
              onChange={(e) => setFullName(e.target.value)}
              required
            />
          </FormGroup>

          {/* Email */}
          <FormGroup>
            <Label>Email</Label>
            <Input
              type="email"
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </FormGroup>

          <Row>
            <Col md={6}>
              {/* Major Dropdown */}
              <FormGroup>
                <Label>Major</Label>
                <Input
                  type="select"
                  value={major}
                  onChange={(e) => setMajor(e.target.value)}
                >
                  {MAJORS.map((m) => (
                    <option key={m}>{m}</option>
                  ))}
                </Input>
              </FormGroup>
            </Col>

            <Col md={6}>
              {/* Student / Graduate Radio */}
              <FormGroup>
                <Label>Status</Label>
                <div className="entity-options">
                  <label>
                    <Input
                      type="radio"
                      value="Student"
                      checked={status === "Student"}
                      onChange={(e) => setStatus(e.target.value)}
                    />{" "}
                    Student
                  </label>
                  <label>
                    <Input
                      type="radio"
                      value="Graduate"
                      checked={status === "Graduate"}
                      onChange={(e) => setStatus(e.target.value)}
                    />{" "}
                    Graduate
                  </label>
                </div>
              </FormGroup>
            </Col>
          </Row>

          {/* Password */}
          <FormGroup>
            <Label>Password</Label>
            <Input
              type="password"
              placeholder="********"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </FormGroup>

          <button className="reg-btn">Sign up</button>

          <p className="login-text">
            Already have an account? <span>Log in now!</span>
          </p>
        </Form>
      </div>
    </div>
  );
};

export default StudentRegister;
